        std::string name(it.sym->name);
        std::string fullName = prefix + "." + name;
        // Implicit nets carry no typespec (and print a bare wire net type).
        bool implicitNet = it.sym->kind == SymbolKind::Net &&
                           it.sym->as<NetSymbol>().isImplicit;

