            auto* cv9 = s.MakeLogic_var();
            cv9->VpiName(name);
            cv9->VpiFullName(fullName);
            cv9->VpiParent(m);
            setLoc(cv9, nameSpan(it.sym->location, it.sym->name));
            cv9->VpiVisibility(1);
            topNets[it.sym] = cv9;
