                            np9->VpiEndLineNo(dp9->VpiEndLineNo());
                            np9->VpiEndColumnNo(dp9->VpiEndColumnNo());
                            std::string pn9(dp9->VpiName());
                            auto* nlc9 = s.MakeRef_obj();
                            nlc9->VpiName(pn9);
                            nlc9->VpiFullName(prefix + "." +
                                              std::string(ucp9.second->name) +
                                              "." + pn9);
