                            nlc9->VpiLineNo(dp9->VpiLineNo());
                            cpFile125(nlc9, dp9);
                            nlc9->VpiColumnNo(dp9->VpiColumnNo());
                            nlc9->VpiEndLineNo(dp9->VpiEndLineNo());
                            nlc9->VpiEndColumnNo(dp9->VpiEndColumnNo());
