                        sv9.setSigned(true);
                        std::string d9 =
                            sv9.toString(LiteralBase::Decimal, false);
                        auto* c9 = s.MakeConstant();
                        c9->VpiDecompile(d9);
                        c9->VpiSize(vw0);
                        c9->VpiValue("INT:" + d9);
                        c9->VpiConstType(vpiIntConst);
                        c9->VpiParent(pv9.var);
                        setLoc(c9, in9.sourceRange);
